"""Original AI-103 alternative labels and explanatory definitions."""
TERMS={}
def t(key,label,meaning):
    if key in TERMS: raise ValueError(f'Duplicate term: {key}')
    TERMS[key]=(label,meaning)
t('modelcatalog', 'Compare supported models in the Foundry model catalog', 'The catalog shows supported models with capability, modality, region, and lifecycle details. Verify availability for your subscription and region before designing around one model.')
t('slm', 'Use a small language model for a narrow, high-volume task', 'Small models can reduce latency and cost for constrained classification or extraction. Confirm quality on representative data before standardizing.')
t('llm', 'Use a general-purpose large language model for complex reasoning', 'Large models handle ambiguity and multi-step reasoning better in many cases, at higher cost and latency. Select with measured evidence rather than brand preference.')
t('multimodal', 'Use a multimodal model for combined text, image, or audio input', 'Multimodal models accept more than one content type in a request. Validate extraction and grounding quality for each modality used.')
t('foundrytools', 'Use Foundry Tools for prebuilt vision, speech, language, and extraction needs', 'Prebuilt managed capabilities can reduce custom model work where their behavior and limits fit the task. They are not a substitute for task-specific validation.')
t('custommodel', 'Train or deploy a task-specific model outside the prebuilt catalog', 'A custom model is justified when supported prebuilt options cannot meet a defined requirement. It adds data, evaluation, and lifecycle obligations.')
t('rag', 'Ground responses with retrieval-augmented generation', 'RAG supplies selected source content at request time so answers can cite current evidence. It reduces but does not eliminate fabrication.')
t('vectorsearch', 'Use a vector index for semantic retrieval', 'Embeddings support similarity search over meaning rather than exact terms. Vector search still needs chunking, filtering, and evaluation.')
t('hybridsearch', 'Combine keyword and vector retrieval', 'Hybrid search covers exact identifiers and paraphrased meaning together. Fusion and ranking need testing on representative queries.')
t('semanticrank', 'Apply semantic ranking to reorder search results', 'A semantic ranker can improve relevance for natural-language queries. It adds cost and latency and should be measured against a baseline.')
t('knowledgeindex', 'Connect an Azure AI Search index as agent knowledge', 'An index gives an agent curated, searchable evidence under configured access. Index content and permissions require ongoing ownership.')
t('memoryservice', 'Use managed conversation state or memory for continuity', 'Managed state supports multi-turn continuity without rebuilding history manually. Retention, isolation, and user control still need design.')
t('toolfunction', 'Expose a typed function as an agent tool', 'Function tools let the agent request a defined operation with structured arguments. Authorization and input validation must be enforced server-side.')
t('openapitool', 'Expose an OpenAPI operation as an agent tool', 'OpenAPI tools describe supported HTTP operations for agent use. Narrow operations, validate inputs, and authenticate the caller.')
t('agentservice', 'Build agents with Foundry Agent Service', 'The managed agent service provides agent definitions, conversation state, and tool integration. You remain responsible for data, tool permissions, and evaluation.')
t('projectendpoint', 'Connect the application to the Foundry project endpoint', 'Project endpoints and SDK clients bind an app to approved models and resources. Use identity-based authentication and environment-specific configuration.')
t('sdk', 'Use a Foundry SDK or supported connector from application code', 'SDKs provide supported request and response patterns. Pin versions and handle retries, timeouts, and errors explicitly.')
t('devops', 'Manage AI resources with infrastructure as code and CI/CD', 'Repeatable deployments reduce configuration drift. Include model deployments, indexes, and connections in review and promotion.')
t('privateendpoint', 'Use private endpoints and disable public network access', 'Private connectivity keeps service traffic on approved network paths. Pair it with private DNS so clients resolve the private address.')
t('managedidentity', 'Authenticate with a managed identity instead of keys', 'Managed identities avoid embedded secrets and support role-based access. Assign only required data-plane roles.')
t('rbac', 'Use least-privilege Azure RBAC roles for the workload identity', 'Roles should match the operations the app or agent performs. Broad contributor access increases blast radius.')
t('keyvault', 'Store secrets in Azure Key Vault when keys are unavoidable', 'A managed secret store supports rotation and access control. Secrets should never appear in prompts, code, or logs.')
t('quota', 'Plan for model quota expressed in tokens and requests per minute', 'Quota limits throughput regardless of application capacity. Request increases in advance and plan graceful degradation.')
t('ptu', 'Use provisioned throughput for predictable high-volume workloads', 'Provisioned capacity reserves throughput at a committed cost. It fits stable demand, not unpredictable spikes.')
t('standarddeploy', 'Use a standard pay-as-you-go model deployment for variable demand', 'Standard deployments bill per token and scale within quota. They suit spiky or early workloads.')
t('batchdeploy', 'Use batch processing for latency-tolerant bulk work', 'Batch deployments can lower cost for large asynchronous jobs. They are unsuitable for interactive agent turns.')
t('cost', 'Track cost per accepted task, not only per token', 'Retries, tool calls, evaluation, and review contribute to unit economics. Per-outcome cost supports better optimization.')
t('monitor', 'Use Azure Monitor and Application Insights for telemetry', 'Central telemetry captures latency, errors, dependencies, and custom events. Redact sensitive content before logging.')
t('drift', 'Monitor input and quality drift over time', 'User behavior, data, and models change. Rolling baselines reveal degradation that a one-time evaluation misses.')
t('groundingmetric', 'Monitor groundedness and citation quality in production', 'Groundedness checks whether claims are supported by retrieved evidence. Sampling and human review complement automated scores.')
t('indexhealth', 'Monitor index freshness, failures, and document counts', 'Stale or partially indexed content produces confident but wrong answers. Alert on ingestion and deletion failures.')
t('contentfilter', 'Configure content safety filters for harmful categories', 'Filters assign severity and can block or annotate content. Thresholds should reflect the use case and applicable policy.')
t('promptshield', 'Enable prompt injection and jailbreak defenses', 'Prompt shields detect direct and indirect manipulation attempts. They are a layer, not a complete authorization boundary.')
t('groundednessdetect', 'Detect ungrounded or fabricated claims at runtime', 'Groundedness detection can flag answers unsupported by supplied context. Use it with evaluation and human escalation.')
t('protectedmaterial', 'Detect protected or copyrighted material in output', 'Detection can reduce distribution risk for generated content. Policy and licensing review still apply.')
t('evaluation', 'Use evaluators for quality, safety, and groundedness', 'Evaluators provide repeatable signals across models and prompts. They must be calibrated against human judgment for high-impact work.')
t('trace', 'Enable tracing across agent, model, and tool calls', 'Traces localize failures and latency in multi-step workflows. Correlate them with evaluation results and deployment versions.')
t('audit', 'Preserve audit logs of changes, approvals, and tool actions', 'Audit evidence supports investigation and accountability. Protect log integrity and retention.')
t('approval', 'Require human approval before consequential actions', 'Approval must occur before the effect and identify who approved what. A model confidence score is not approval.')
t('oversight', 'Set agent oversight mode and tool-access constraints', 'Oversight settings bound what an agent may do autonomously. They should be tested against realistic misuse and failure.')
t('guardrail', 'Enforce constraints in code and platform policy', 'Guardrails are technical controls, not prompt suggestions. Validate inputs, authorize tools, and limit egress.')
t('redteam', 'Test the solution with adversarial and boundary cases', 'Red-team cases expose prompt injection, data leakage, and unsafe tool use. Findings should become regression tests.')
t('citation', 'Require citations tied to retrieved evidence', 'Citations let users verify claims and support auditing. Preserve source and chunk identifiers through the pipeline.')
t('chunking', 'Choose chunk size and overlap for retrieval quality', 'Chunking affects recall, precision, and context use. Respect document structure and test against real questions.')
t('embedding', 'Choose an embedding model suited to the content and language', 'Embeddings determine semantic similarity behavior. Evaluate retrieval quality before and after changes.')
t('ingest', 'Ingest content through supported indexers or APIs', 'Ingestion moves source content into a searchable index. Handle failures, updates, and deletions explicitly.')
t('ocr', 'Apply OCR to convert images and scans into usable text', 'OCR unlocks text in scans and screenshots. Layout and table structure may still require specialized extraction.')
t('layout', 'Preserve document layout, tables, and reading order', 'Layout awareness improves extraction from forms and multi-column documents. Flattening to plain text can destroy meaning.')
t('enrichment', 'Add enrichment skills for text, image, and layout', 'A skillset can extract entities, captions, and structure during indexing. Enrichment adds cost and failure points that need monitoring.')
t('markdown', 'Produce markdown representations for downstream reasoning', 'Markdown preserves headings, tables, and lists in a model-friendly form. Validate that critical values survive conversion.')
t('structuredoutput', 'Return a defined JSON schema for downstream systems', 'Structured output supports validation and automation. Schema validity does not prove semantic correctness.')
t('schema', 'Define field names, types, and required values', 'A clear schema reduces ambiguity and enables validation. Include handling for missing or unknown values.')
t('confidence', 'Capture confidence or uncertainty for extracted fields', 'Confidence helps route low-quality results to review. It is not a guarantee of correctness.')
t('humanreview', 'Route low-confidence or high-impact results to human review', 'Review targets uncertainty and consequence rather than every item. Define who decides and what evidence they receive.')
t('sentiment', 'Analyze sentiment and tone with an appropriate service', 'Sentiment analysis can support triage and monitoring. Domain and language variation require validation.')
t('pii', 'Detect and redact sensitive personal data', 'Sensitive Data Protection or language PII detection can identify and mask data. Verify that redaction covers every path where content flows.')
t('summarize', 'Generate summaries with explicit length and audience constraints', 'Summaries should preserve required facts and caveats. Fluency does not prove completeness.')
t('entity', 'Extract entities with defined types and boundaries', 'Entity extraction turns text into structured facts. Ambiguous mentions need resolution and validation.')
t('topic', 'Identify topics or key phrases for navigation', 'Topic extraction supports discovery and grouping. It is not a substitute for an authoritative taxonomy.')
t('structuredjson', 'Prompt for JSON that conforms to a supplied schema', 'Schema-guided generation improves machine readability. Validate values against source evidence and business rules.')
t('translate', 'Use Azure Translator or a language model for translation', 'Translation should preserve meaning, names, and formatting. Evaluate domain terminology and low-resource languages.')
t('glossary', 'Apply a custom glossary or terminology list', 'Glossaries keep product and legal terms consistent. Terms still need human validation in context.')
t('speechtotext', 'Transcribe speech to text with Azure AI Speech', 'Speech-to-text enables voice agents and transcript analysis. Audio quality, accents, and domain terms affect accuracy.')
t('texttospeech', 'Synthesize speech with Azure AI Speech', 'Text-to-speech supports voice responses and accessibility. Voice, prosody, and latency affect usability.')
t('customspeech', 'Use a custom speech model for specialized vocabulary', 'Custom speech can improve recognition of domain terms. It requires representative audio and ongoing evaluation.')
t('speechtranslation', 'Translate spoken language with speech translation', 'Speech translation combines recognition and translation. Preserve timing and speaker context where needed.')
t('audioreasoning', 'Use a multimodal model to reason over audio content', 'Audio-capable models can summarize or answer questions about recordings. Verify transcription quality and evidence grounding.')
t('compliance', 'Customize summaries and extraction for compliance needs', 'Compliance work requires precise citation, retention, and review. Generic summarization is insufficient without controls.')
t('domainlexicon', 'Adapt prompts and models to domain terminology', 'Domain adaptation improves consistency and recall. Validate against expert-created expected outputs.')
t('visiongen', 'Generate images from text and reference media', 'Image generation supports creative and product workflows. Apply policy, watermarking, and provenance controls.')
t('inpainting', 'Edit a region of an image with a mask', 'Inpainting changes a selected area while preserving the rest. Validate identity, brand, and safety constraints.')
t('imageedit', 'Apply prompt-driven image modifications', 'Prompt-based edits can alter style or content. Review outputs for unintended changes and policy violations.')
t('videogen', 'Generate video from text or reference media', 'Video generation creates clips from prompts or images. Duration, consistency, and safety require review.')
t('videoedit', 'Edit generated video segments', 'Video editing can revise scenes or timing. Preserve provenance and review for harmful manipulation.')
t('caption', 'Generate concise or detailed image captions', 'Captions describe visual content for users or downstream systems. Match detail to the audience and purpose.')
t('alttext', 'Generate alt text aligned to accessibility guidance', 'Alt text should convey purpose and essential content, not decorative detail. Human review is still needed for critical pages.')
t('vqa', 'Answer questions grounded in visual evidence', 'Visual question answering should cite the relevant region or content. Avoid answering beyond what the image supports.')
t('contentunderstanding', 'Use Azure Content Understanding analyzers in Foundry Tools', 'Content Understanding extracts structure and fields from documents, images, audio, and video. Analyzer design and validation determine quality.')
t('promode', 'Use pro mode for complex multimodal content understanding', 'Pro mode handles more demanding layouts and multimodal inputs at higher cost. Use it where simpler modes fail requirements.')
t('singletask', 'Use single-task mode for a focused extraction scenario', 'Single-task analyzers target one content type or objective. They may be simpler and cheaper than general pro-mode pipelines.')
t('objectdetect', 'Identify objects, components, or regions in visual content', 'Detection returns locations and labels for visual elements. Validate classes and thresholds against the use case.')
t('videoanalysis', 'Analyze video segments for events and content', 'Video analysis can summarize or detect events across time. Sampling strategy affects coverage and cost.')
t('visualfilter', 'Filter unsafe or disallowed visual content', 'Image and video safety filters reduce exposure to harmful content. Thresholds and human escalation should match policy.')
t('indirectinjection', 'Treat text embedded in images as untrusted input', 'Visible instructions in images can attempt to manipulate an agent. Isolate, detect, and never let image text grant authority.')
t('watermark', 'Apply watermarks or provenance markers to generated media', 'Watermarks support disclosure and traceability. They do not replace usage policy or review.')
t('brandpolicy', 'Enforce brand and usage rules for generated visuals', 'Brand controls define permitted logos, styles, and claims. Technical generation must still pass approval.')
t('objectsafety', 'Flag prohibited symbols or inappropriate content', 'Visual policy checks can detect disallowed imagery. Combine automated checks with escalation for ambiguous cases.')
t('indexer', 'Use an Azure AI Search indexer to pull source content', 'Indexers automate ingestion and can run on a schedule. Monitor failures, deletions, and field mappings.')
t('pushapi', 'Push documents to an index through the data-plane API', 'Push ingestion supports near-real-time updates from applications. The app owns batching, retries, and deletion.')
t('integratedvector', 'Use integrated vectorization during indexing', 'Integrated vectorization generates embeddings as part of the ingestion pipeline. Model or schema changes require reindexing.')
t('skillset', 'Add an enrichment skillset to an indexing pipeline', 'Skillsets can OCR, split, embed, and extract during indexing. Each skill adds latency, cost, and failure modes.')
t('securityfilter', 'Apply document-level security filters at query time', 'Filters restrict results to content the user may see. They must be enforced before content reaches the model.')
t('freshness', 'Verify index freshness and deletion propagation', 'Stale content produces outdated answers. Define refresh expectations and test deletion behavior.')
t('citationchunk', 'Preserve chunk and source identifiers for citations', 'Identifiers connect answers to supporting passages. Losing them breaks verification and audit.')
t('rerank', 'Rerank retrieved passages before generation', 'Reranking improves precision after broad recall. It adds latency and must be evaluated.')
t('contextbudget', "Select evidence within the model's usable context", 'More retrieved text is not always better. Order and compress evidence to preserve decisive facts.')
t('multimodalindex', 'Index images, audio, and video alongside text', 'Multimodal indexing broadens retrieval but requires extraction and metadata. Validate search quality per modality.')
t('docintel', 'Use Azure AI Document Intelligence for forms and documents', 'Document Intelligence provides prebuilt and custom extraction for structured documents. Validate field accuracy on representative samples.')
t('customextract', 'Train a custom extraction model on labeled documents', 'Custom models fit specialized forms not covered by prebuilts. They require representative labels and retraining discipline.')
t('prebuilt', 'Use a prebuilt document model for common document types', 'Prebuilt models cover invoices, receipts, IDs, and similar formats. Check supported locales and field coverage.')
t('analyzer', 'Configure a Content Understanding analyzer for the content type', 'Analyzers define what to extract and how to return it. Version and test them like application code.')
t('markdownoutput', 'Return markdown for retrieval and reasoning pipelines', 'Markdown preserves structure and is easy for models to consume. Validate tables and key values.')
t('structuredfields', 'Return typed fields for automation', 'Typed fields feed downstream systems directly. Add validation and confidence thresholds before automated action.')
t('ocrlayout', 'Combine OCR with layout analysis for complex documents', 'OCR supplies text while layout analysis preserves relationships. Together they support tables and multi-column forms.')
t('readingorder', 'Preserve reading order across columns and sections', 'Reading order affects comprehension and extraction. Incorrect order can invert meaning in contracts and forms.')
t('tablerecovery', 'Recover table structure from scanned documents', 'Tables require structural extraction, not only text. Validate row and column alignment on representative scans.')
t('fieldconfidence', 'Use field-level confidence to route exceptions', 'Low-confidence fields should be reviewed rather than accepted. Thresholds depend on downstream impact.')
t('idempotent', 'Make ingestion and tool actions idempotent', 'Retries should not duplicate documents or actions. Use stable identifiers and deduplication.')
t('deleteprop', 'Propagate source deletions to indexes and caches', 'Removed content must stop appearing in answers. Test deletion propagation explicitly.')
t('accesstoken', 'Use short-lived scoped access tokens for tool calls', 'Short-lived credentials reduce misuse risk. Never place tokens in prompts or logs.')
t('egress', 'Restrict outbound network access to approved destinations', 'Egress controls reduce exfiltration and unauthorized tool reach. Combine with identity and data controls.')
t('private dns', 'Configure private DNS for private endpoint resolution', 'Private endpoints require correct name resolution. Missing DNS records cause clients to fall back or fail.')
t('diagnostic', 'Send resource diagnostic logs to a central workspace', 'Diagnostic settings capture control-plane and data-plane events. Correlate them with application telemetry.')
t('alert', 'Alert on latency, error rate, safety, and cost thresholds', 'Alerts turn monitoring into action. Route them to an accountable owner with a runbook.')
t('rollout', 'Use staged rollout with measurable rollback criteria', 'Canary or phased rollout limits exposure. Rollback must be tested, not just documented.')
t('abtest', 'Compare variants with controlled traffic and shared metrics', 'Controlled comparison supports evidence-based change. Avoid changing several variables at once.')
t('regression', 'Re-run evaluation suites after meaningful changes', 'Prompts, models, indexes, and tools all affect behavior. Regression tests catch unintended effects.')
t('golden', 'Build a representative golden dataset from real tasks', 'A golden set anchors evaluation in expected behavior. Include edge cases and high-risk scenarios.')
t('fabrication', 'Detect fabricated or unsupported statements', 'Fabrication checks compare claims with evidence. Fluency and confidence are not evidence of accuracy.')
t('relevance', 'Measure whether retrieved content and answers address the question', 'Relevance covers both retrieval and response usefulness. A correct but off-topic answer still fails.')
t('coherence', 'Evaluate structure and logical consistency of responses', 'Coherence checks readability and internal consistency. It does not establish factual accuracy.')
t('safetyeval', 'Evaluate harmful, biased, or policy-violating output', 'Safety evaluation complements content filters. Use representative adversarial inputs.')
t('tone', 'Detect tone and sentiment appropriate to the audience', 'Tone analysis supports brand and customer communication. Context and culture affect interpretation.')
t('conversationthread', 'Persist conversation history in a thread or session', 'Threads support continuity across turns. Apply retention and access controls to stored history.')
t('toolsschema', 'Define narrow tool schemas with clear descriptions', 'Precise schemas help the model choose tools and arguments correctly. Broad or ambiguous tools invite unsafe calls.')
t('multistep', 'Design multistep workflows with explicit checkpoints', 'Checkpoints validate intermediate results before later steps depend on them. This limits error propagation.')
t('handoff', 'Transfer control between agents with explicit context', 'Handoffs should carry goal, evidence, permissions, and open questions. Implicit context is easily lost.')
t('sequentialagent', 'Run agents in a fixed sequence', 'Sequential orchestration makes dependencies explicit. It may add latency where steps could run concurrently.')
t('parallelagent', 'Run independent agents concurrently', 'Parallel execution reduces wall-clock time for independent work. Reconciliation still requires design.')
t('manageragent', 'Use a manager agent to coordinate specialists', 'A manager routes tasks and merges results. Clear responsibility and failure handling are required.')
t('connectedagent', 'Connect specialist agents as tools to an orchestrator', 'Connected agents let one agent delegate to another. Authorization and result validation remain necessary.')
t('approvalflow', 'Insert an approval step before high-impact actions', 'Approval flows prevent unreviewed commitments. Bind approval to the specific action and evidence.')
t('autonomous', 'Limit autonomy with scope, budget, and stop conditions', 'Autonomous workflows need bounded actions and escalation. Unbounded loops and broad tools increase risk.')
t('reflection', 'Use self-critique or reflection to improve drafts', 'Reflection can catch omissions and inconsistencies. It can also reinforce errors, so validate against evidence.')
t('temperature', 'Lower temperature for more deterministic extraction', 'Lower temperature reduces sampling variability. It does not guarantee factual correctness.')
t('topp', 'Adjust top-p to control response diversity', 'Top-p narrows or broadens token sampling. Tune with evaluation rather than by intuition.')
t('systemmessage', 'Put stable behavior rules in the system message', 'System messages define role and constraints. They are not a security boundary against injection.')
t('prompttemplate', 'Use a versioned prompt template with explicit variables', 'Templates improve consistency and reviewability. Version them and test changes.')
t('fewshot', 'Include representative examples in the prompt', 'Examples clarify format and boundaries. They do not guarantee correctness on unseen inputs.')
t('tokenanalytics', 'Track prompt, completion, and cached token usage', 'Token analytics supports cost and performance tuning. Attribute usage to features and tenants where possible.')
t('latency', 'Measure end-to-end latency across model, retrieval, and tools', 'Users experience the whole path, not only generation. Optimize the dominant contributor.')
t('cache', 'Use supported prompt or response caching where appropriate', 'Caching can reduce cost and latency for repeated content. Validate correctness and invalidation behavior.')
t('router', 'Route requests to different models by task difficulty', 'Routing can balance quality and cost. Fallback and evaluation are required.')
t('rulesengine', 'Combine deterministic rules with LLM reasoning', 'Rules handle policy and exact computations; the model handles language. Define which component is authoritative.')
t('seqragok','Ingest → extract text → chunk → embed → index → retrieve with citations','The supported RAG ingestion order produces searchable, citable evidence. Retrieval cannot work before content is extracted, chunked, embedded, and indexed.')
t('seqragbad1','Ingest → retrieve → chunk → embed → index → cite','Retrieval before chunking, embedding, and indexing has nothing searchable to return.')
t('seqragbad2','Chunk → embed → ingest → retrieve → index → cite','Retrieval is attempted before the index exists and source ingestion is incomplete.')
t('seqragbad3','Index → retrieve → ingest → chunk → embed → cite','Indexing before extraction or embedding creates an empty or unusable index.')
t('seqdeployok','Provision resources → deploy model → configure app connection → evaluate → promote','Provisioning and deployment precede app configuration, and evaluation gates promotion.')
t('seqdeploybad1','Deploy model → promote → provision resources → evaluate → configure app','Promotion before provisioning and evaluation skips the controls that make deployment safe.')
t('seqdeploybad2','Configure app → provision resources → deploy model → promote → evaluate','Evaluation after promotion cannot gate the release.')
t('seqdeploybad3','Evaluate → provision resources → promote → deploy model → configure app','Evaluation before any deployment or configuration has nothing meaningful to assess.')
t('seqtoolok','Model requests tool → app validates and authorizes → tool executes → result returns → model responds','Tool execution authority belongs to the application, which validates and authorizes before acting.')
t('seqtoolbad1','Model executes tool → app validates → tool returns result → app authorizes → model responds','The model cannot execute the tool, and authorization after execution is too late.')
t('seqtoolbad2','App authorizes → model executes tool → result returns → app validates → model responds','Execution must follow validation, and the model is not the execution boundary.')
t('seqtoolbad3','Model responds → app authorizes → tool executes → result returns → app validates','The response cannot precede the tool action and validation.')
t('seqspeechok','Capture audio → transcribe → translate text → synthesize speech → return audio','Speech translation transcribes first, translates the text, then synthesizes the target-language audio.')
t('seqspeechbad1','Capture audio → synthesize speech → transcribe → translate → return audio','Synthesis cannot precede transcription and translation.')
t('seqspeechbad2','Translate audio → transcribe → capture audio → synthesize → return audio','Audio must be captured before it can be transcribed or translated.')
t('seqspeechbad3','Transcribe → synthesize speech → capture audio → translate → return audio','Capture must come first, and synthesis must follow translation.')
t('seqagentok','Define role and goal → configure tools → attach knowledge → evaluate in sandbox → deploy with monitoring','An agent is defined before it is connected to tools and knowledge, and evaluation precedes deployment.')
t('seqagentbad1','Deploy with monitoring → define role and goal → configure tools → evaluate in sandbox → attach knowledge','Deployment before the agent is defined, connected, or evaluated removes every control.')
t('seqagentbad2','Configure tools → deploy with monitoring → define role and goal → attach knowledge → evaluate in sandbox','Tools configured before the role exists, and evaluation after deployment gates nothing.')
t('seqagentbad3','Attach knowledge → configure tools → deploy with monitoring → define role and goal → evaluate in sandbox','The agent must be defined first, and evaluation must precede deployment.')
t('seqimageok','Upload image → validate format and size → send multimodal request → parse structured fields → route low-confidence values to review','Validation and structured parsing bracket the multimodal call, and low-confidence output goes to people.')
t('seqimagebad1','Send multimodal request → upload image → validate format → parse structured fields → review','A request cannot precede the upload, and validation must come before the call.')
t('seqimagebad2','Parse structured fields → send multimodal request → upload image → validate format → review','Parsing requires a response, which requires an uploaded and validated image.')
t('seqimagebad3','Validate format → review → upload image → parse structured fields → send multimodal request','Review cannot precede the request, and parsing must follow the response.')
t('seqevalok','Define quality criteria → assemble labeled cases → run evaluators → compare variants → release with monitoring','Criteria and ground truth come before measurement, and monitoring follows the release.')
t('seqevalbad1','Compare variants → release with monitoring → define quality criteria → assemble labeled cases → run evaluators','Variant comparison before criteria and ground truth is not a measurement.')
t('seqevalbad2','Release with monitoring → run evaluators → define quality criteria → compare variants → assemble labeled cases','Releasing first defeats the purpose, and criteria must precede evaluation.')
t('seqevalbad3','Run evaluators → define quality criteria → compare variants → assemble labeled cases → release with monitoring','Evaluators need criteria and labeled cases before they can produce comparable scores.')
t('seqincidentok','Detect alert → inspect traces → isolate the failing step → apply fix → verify with regression evaluation','Triage moves from signal to evidence to a targeted fix, then proves the fix with regression tests.')
t('seqincidentbad1','Apply fix → detect alert → inspect traces → isolate the failing step → verify with regression evaluation','A fix cannot precede detection and diagnosis.')
t('seqincidentbad2','Verify with regression evaluation → apply fix → detect alert → isolate the failing step → inspect traces','Verification before a fix and before diagnosis proves nothing.')
t('seqincidentbad3','Isolate the failing step → apply fix → detect alert → verify with regression evaluation → inspect traces','The alert must be detected first, and traces must be inspected before the step is isolated.')
t('manualportal','Create and run deployments by hand in the portal','Manual portal changes work for exploration but are slow, undocumented, and hard to reproduce, so they are a poor fit for governed release processes.')
t('singlecall','One model call with no external retrieval or tool use','A single call cannot validate intermediate results or fetch authoritative evidence, so it is unsuitable for multi-stage or grounded workflows.')
t('apikey','Long-lived API key pasted into configuration','Static keys are easily leaked, hard to rotate across services, and provide no per-identity authorization.')
t('connectionstring','Shared connection string with an embedded secret','A shared secret grants broad access, cannot be scoped per workload, and complicates rotation and auditing.')
t('private','Private networking with public access left enabled','Leaving the public path open defeats the purpose of a private networking design because traffic can still bypass the private route.')
t('dns','Private DNS resolution configured for the endpoint','Name resolution alone does not block public access, so it must be paired with a private endpoint and public access disabled.')
t('dedupe','Remove near-duplicate evidence before ranking','De-duplication frees context space that duplicates would otherwise consume, so the most informative evidence survives the budget.')
t('translation','Translate every request before retrieval','Translating the request does not replace retrieval, grounding, or validation, so it cannot satisfy an evidence or citation requirement.')
t('facetags','Generate a set of descriptive tags for each image','Tags support filtering and search across large image libraries. Tag vocabulary should be governed so synonyms do not fragment results.')
t('imageretrieval','Index image embeddings and search by visual similarity','Visual search returns near-duplicate or stylistically similar images from an indexed library. It complements, rather than replaces, metadata filters.')
t('moderationreview','Queue flagged generations for human moderation before release','Human moderation catches context that automated filters miss, at the cost of latency and reviewer load.')
t('styleTransfer','Apply a consistent visual style to generated images','Style control keeps campaign output recognizable across many generations. It does not guarantee factual accuracy of depicted content.')
t('keyphrases','Extract key phrases to summarize what a document covers','Key phrases support navigation, tagging, and clustering. They are not a substitute for a required structured field.')
t('entitylinking','Link detected entities to a known entity catalog','Entity linking resolves ambiguous names to canonical records, which enables joins. It depends on catalog quality and disambiguation thresholds.')
t('abstractive','Generate an abstractive summary in new wording','Abstractive summaries read naturally and compress long text, but they can introduce statements that the source does not support.')
t('extractive','Select and return the most relevant source sentences','Extractive summaries stay verbatim and therefore auditable, at the cost of readability and length.')
t('profanityfilter','Apply a profanity mask to generated text output','Masking keeps generated content presentable in regulated channels. It is a presentation control, not a safety evaluation of the underlying model.')
t('chunkoverlap','Set chunk overlap so facts spanning a boundary stay retrievable','Overlap preserves context across chunk edges at the cost of duplicated index storage and more near-duplicate hits.')
t('indexschema','Define index fields, attributes, and searchable versus filterable behavior','Field attributes decide what can be filtered, sorted, faceted, or retrieved, so schema choices constrain query design later.')
t('pagination','Page results with continuation parameters for large result sets','Paging keeps responses bounded for clients and avoids timeouts on large matches. It is not a relevance control.')
t('relevancetuning','Tune scoring and boosting against a labelled query set','Boosting and scoring changes should be measured on real queries. Untested tuning usually trades one query class for another.')
t('filetool','Give the agent a file-search tool over approved document stores','A file tool retrieves from curated stores under configured access. It still depends on indexing quality and permission filters.')
t('codeinterpreter','Enable a sandboxed code interpreter tool for calculations','Code execution handles quantitative work the model cannot do reliably in text. The sandbox must be isolated and output must be validated.')
t('agentversion','Pin the agent definition version used by the deployment','Pinning makes behavior reproducible and rollback measurable. Unpinned agents can change silently when instructions or tools change.')
t('longtermmemory','Persist durable user preferences in long-term memory','Long-term memory personalizes across sessions but raises retention, consent, and correction obligations.')
t('commitgate','Block promotion in the pipeline when evaluation thresholds fail','An automated gate turns an evaluation result into a release decision. Thresholds need ownership or the gate becomes noise.')
t('shadowdeploy','Send mirrored production traffic to a candidate without returning its answers','Shadow traffic compares a candidate against live behavior with no user impact. It requires careful handling of side-effecting calls.')
t('canaryrollout','Shift a small traffic percentage to the new version first','A canary limits blast radius and produces real signal before full rollout. It needs a rollback criterion defined in advance.')
t('budgetalert','Alert on spend thresholds per deployment or project','Spend alerts catch runaway usage before the invoice does. They are detection, not a hard spending cap.')
t('regionpinning','Pin the model version available in the required region','A pinned version keeps behavior stable and satisfies residency, at the cost of slower access to newer capabilities.')
t('videotranscript','Transcribe speech from video as part of analysis','Transcripts make video content searchable and reviewable. Alignment with frames is needed for precise event timing.')
t('transliteration','Convert names between writing systems without translating meaning','Transliteration preserves pronunciation for names and addresses. It is not a substitute for translating meaning-bearing text.')
t('seqgateok','Commit change → run the evaluation suite → block on failed thresholds → deploy a canary → promote after metrics hold',
  'An evaluation gate before deployment, followed by a canary, keeps unmeasured changes away from all users.')
t('seqgatebad1','Deploy a canary → commit change → promote after metrics hold → run the evaluation suite → block on failed thresholds',
  'Deployment cannot precede the change, and evaluation must gate promotion rather than follow it.')
t('seqgatebad2','Run the evaluation suite → deploy a canary → commit change → block on failed thresholds → promote after metrics hold',
  'The change must exist before it can be evaluated or deployed.')
t('seqgatebad3','Commit change → deploy a canary → promote after metrics hold → run the evaluation suite → block on failed thresholds',
  'Evaluation after promotion cannot prevent a failed change from reaching everyone.')
t('seqindexok','Connect the data source → define the index schema → attach the enrichment skillset → run the indexer → validate relevance on sample queries',
  'Schema and enrichment must exist before indexing runs, and relevance is checked after the index is populated.')
t('seqindexbad1','Run the indexer → connect the data source → define the index schema → attach the enrichment skillset → validate relevance on sample queries',
  'An indexer cannot run before the source and schema exist.')
t('seqindexbad2','Validate relevance on sample queries → run the indexer → connect the data source → define the index schema → attach the enrichment skillset',
  'Relevance cannot be validated on an index that was never populated.')
t('seqindexbad3','Attach the enrichment skillset → connect the data source → validate relevance on sample queries → define the index schema → run the indexer',
  'The schema must exist before enrichment and relevance testing.')
t('seedparam','Set a seed parameter for reproducible sampling where the provider supports it','A seed makes repeated sampling closer to reproducible, but it remains best effort and does not replace deterministic extraction settings.')
t('stopsequence','Set a stop sequence so generation ends at the intended boundary','A stop sequence truncates output at a defined marker, which keeps parsers from receiving trailing commentary. It must not appear inside legitimate content.')
t('speechsynthesisvoice','Select a specific synthesis voice for consistent spoken output','A named voice keeps a phone or kiosk channel recognizable across prompts. Voice availability and language coverage vary by region.')
